const base='/api/marketplace/quotations';
export async function renderQuotations(root,current){const add=(tag,text,p=root)=>{const e=document.createElement(tag);e.textContent=text;p.append(e);return e;};async function api(path='',body){const r=await fetch(base+path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok||!j.success)throw Error(j.error||'Unavailable');return j;}const load=async()=>{const {quotations}=await api();if(!current())return;root.replaceChildren();add('h2','Quotations');if(!quotations.length)add('p','No quotations yet.');for(const q of quotations){const p=add('section','');p.className='workspace-session';const money=n=>new Intl.NumberFormat(undefined,{style:'currency',currency:q.currency}).format(n/100);add('h3','Quotation '+q.id+' / revision '+q.revision,p);add('p','Request '+q.request_id+' · '+q.status,p);for(const i of q.items)add('p',i.description+' × '+i.quantity+' · '+money(i.unit_minor),p);add('p','Total: '+money(q.total_minor)+' | Discount: '+money(q.discount_minor)+' | Deposit: '+money(q.deposit_minor),p);add('p',q.terms,p);add('p','Valid until '+new Date(q.expires_at).toLocaleString(),p);if(q.response_note)add('p',q.response_note,p);if(q.status==='sent'&&Date.parse(q.expires_at)>Date.now()){const note=add('textarea','',p);note.maxLength=4000;note.placeholder='Response or revision details';for(const [label,status] of [['Accept','accepted'],['Decline','declined'],['Request revision','revision_requested']]){const b=add('button',label,p);b.onclick=async()=>{if(!confirm(label+' this quotation?'))return;b.disabled=true;try{await api('/'+q.id+'/respond',{status,note:note.value});await load();}catch(e){add('p',e.message,p);b.disabled=false;}};}}}};try{await load();}catch(e){if(current())add('p',e.message);}}
